import{_ as e,o as t,c as o,a5 as l}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"安裝 Konado","description":"","frontmatter":{"title":"安裝 Konado","order":1},"headers":[],"relativePath":"tc/latest/tutorial/install.md","filePath":"tc/latest/tutorial/install.md","lastUpdated":1788455378000}'),r={name:"tc/latest/tutorial/install.md"};function i(n,a,d,s,h,c){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="安裝-konado" tabindex="-1">安裝 Konado <a class="header-anchor" href="#安裝-konado" aria-label="Permalink to &quot;安裝 Konado&quot;">​</a></h1><h2 id="依賴環境" tabindex="-1">依賴環境 <a class="header-anchor" href="#依賴環境" aria-label="Permalink to &quot;依賴環境&quot;">​</a></h2><p>最低支援 <strong>Godot 4.7.1</strong>。</p><p>以下 Godot 版本均經過開發者測試，可以正常使用：</p><ul><li>4.7.1</li></ul><h3 id="插件下載" tabindex="-1">插件下載 <a class="header-anchor" href="#插件下載" aria-label="Permalink to &quot;插件下載&quot;">​</a></h3><h4 id="穩定版-推薦" tabindex="-1">穩定版（推薦） <a class="header-anchor" href="#穩定版-推薦" aria-label="Permalink to &quot;穩定版（推薦）&quot;">​</a></h4><p>請前往 <a href="https://github.com/godothub/konado/releases/latest" target="_blank" rel="noreferrer">Konado 最新版本頁面</a> 下載最新穩定版插件 ZIP 壓縮包。穩定版經過充分驗證，穩定性和可靠性更有保障，是生產環境的首選。</p><p>為提升中國大陸地區使用者的下載體驗，推薦使用此最佳化連結取得資源：<a href="https://atomgit.com/godothub/konado/releases" target="_blank" rel="noreferrer">Release 連結</a>，此連結可有效改善下載速度。</p><h2 id="安裝步驟" tabindex="-1">安裝步驟 <a class="header-anchor" href="#安裝步驟" aria-label="Permalink to &quot;安裝步驟&quot;">​</a></h2><ol><li>在 Godot 工程目錄新建插件資料夾 <code>addons</code></li><li>下載 release 的插件 zip 包</li><li>解壓到 <code>addons</code> 目錄下</li><li>在 Godot 專案設定中啟用插件，並重新載入目前專案</li></ol><h2 id="開發團隊寄語" tabindex="-1">開發團隊寄語 <a class="header-anchor" href="#開發團隊寄語" aria-label="Permalink to &quot;開發團隊寄語&quot;">​</a></h2><p>你已成功安裝 Konado 插件。在正式開始創作前，想與你分享一段寄語：</p><blockquote><p>「 對於任何行業來說，想像力配上一絲智慧，都是無堅不摧的武器。」</p><p>—— 菲利普·K·迪克（Philip K. Dick） 《少數派報告》（<em>Minority Report</em>，1956）</p></blockquote><p>願你始終保有想像力與精益求精的態度，在創作之路上探索更多可能。</p>',15)])])}const _=e(r,[["render",i]]);export{u as __pageData,_ as default};
